/* Content hidden state */
.e-n-accordion-item > div[role="region"] {
  overflow: hidden;
  max-height: 0;          /* start collapsed */
  opacity: 0;
  transform: translateY(20px);  /* slide up effect */
  transition: 
    max-height 0.5s ease-in-out,
    opacity 0.4s ease-in-out,
    transform 0.4s ease-in-out;
}

/* Content visible state */
.e-n-accordion-item[open] > div[role="region"] {
    margin-top: -90px;
  max-height: 250px;    /* big enough to fit content */
  opacity: 1;
  transform: translateY(0);
  transition: all 0.4s ease-in-out;
}

/* Optional: smooth fade out header */
.e-n-accordion-item > summary {
  transition: opacity 0.4s ease;
}

.e-n-accordion-item[open] > summary {
  opacity: 0;
  pointer-events: none;
}

